uv run python -c '
from pathlib import Path
import re, sys
root = Path('"'"'/home/ntdm/dev/lap-in-the-loop'"'"')
docs = root / '"'"'docs'"'"'
files = ['"'"'notes/use-case-lab-in-the-loop.md'"'"', '"'"'system-architecture.md'"'"', '"'"'development-roadmap.md'"'"', '"'"'experiment-workflow.md'"'"', '"'"'lab-in-the-loop-use-case-specification.md'"'"', '"'"'setup-and-operations.md'"'"', '"'"'project-changelog.md'"'"']
errors = []
for relative in files:
    path = docs / relative
    text = path.read_text(encoding='"'"'utf-8'"'"')
    for raw in re.findall(r'"'"'(?<!!)\[[^\]]*\]\(([^)]+)\)'"'"', text):
        target = raw.strip().split()[0].split('"'"'#'"'"', 1)[0]
        if not target or target.startswith(('"'"'#'"'"', '"'"'http://'"'"', '"'"'https://'"'"', '"'"'mailto:'"'"', '"'"'tel:'"'"')):
            continue
        if not (path.parent / target).resolve().exists():
            errors.append(f'"'"'broken local link {relative} -> {raw}'"'"')
for relative in files:
    if len((docs / relative).read_text(encoding='"'"'utf-8'"'"').splitlines()) > 800:
        errors.append(f'"'"'over 800 lines: {relative}'"'"')
ops = (docs / '"'"'setup-and-operations.md'"'"').read_text(encoding='"'"'utf-8'"'"')
config_names = ['"'"'LAB_AGENT_ROUTING_TABLE'"'"', '"'"'LAB_AGENT_PROVIDER_ENDPOINTS'"'"', '"'"'LAB_AGENT_PROVIDER_DATA_CLASSIFICATIONS'"'"', '"'"'LAB_AGENT_PRICING_VERSION'"'"', '"'"'LAB_AGENT_MODEL_PRICING'"'"', '"'"'LAB_AGENT_RUN_TOKEN_BUDGET'"'"', '"'"'LAB_AGENT_RUN_COST_BUDGET_USD'"'"', '"'"'LAB_AGENT_CANVAS_TOKEN_BUDGET'"'"', '"'"'LAB_AGENT_CANVAS_COST_BUDGET_USD'"'"', '"'"'LAB_AGENT_WALL_TIME_BUDGET_SECONDS'"'"', '"'"'LAB_AGENT_NO_PROGRESS_ROUNDS'"'"', '"'"'LAB_AGENT_MODEL_CALL_MAX_ATTEMPTS'"'"', '"'"'LAB_AGENT_MODEL_MAX_OUTPUT_TOKENS'"'"']
for name in config_names:
    if name not in ops:
        errors.append(f'"'"'missing config: {name}'"'"')
markers = {
    '"'"'project-changelog.md'"'"': '"'"'## 2026-07-19 — Phase 5: governance and model routing'"'"',
    '"'"'development-roadmap.md'"'"': '"'"'Complete for local/source gates — Phase 5 implementation verified 2026-07-19'"'"',
    '"'"'lab-in-the-loop-use-case-specification.md'"'"': '"'"'Complete for local/source gates on 2026-07-19'"'"',
    '"'"'system-architecture.md'"'"': '"'"'### Governance and model routing (Phase 5)'"'"',
    '"'"'experiment-workflow.md'"'"': '"'"'## Governance at model-call boundaries'"'"',
    '"'"'setup-and-operations.md'"'"': '"'"'### Governance and model routing'"'"',
}
for relative, marker in markers.items():
    if marker not in (docs / relative).read_text(encoding='"'"'utf-8'"'"'):
        errors.append(f'"'"'missing status marker: {relative}'"'"')
architecture = (docs / '"'"'system-architecture.md'"'"').read_text(encoding='"'"'utf-8'"'"')
roadmap = (docs / '"'"'development-roadmap.md'"'"').read_text(encoding='"'"'utf-8'"'"')
spec = (docs / '"'"'lab-in-the-loop-use-case-specification.md'"'"').read_text(encoding='"'"'utf-8'"'"')
workflow = (docs / '"'"'experiment-workflow.md'"'"').read_text(encoding='"'"'utf-8'"'"')
for stale in ['"'"'Token/resource governance, model routing, and multi-user observability do not exist yet'"'"', '"'"'today: only `LAB_AGENT_LOOP_MAX_ROUNDS` as a runaway backstop'"'"', '"'"'today: none — mock robot only, no human-approval gate in code'"'"']:
    if stale in architecture:
        errors.append('"'"'stale architecture wording'"'"')
if re.search(r'"'"'Phase 4b[^\n]*(?:\n[^\n]*){0,6}?Status[^\n]*Future'"'"', roadmap, re.I):
    errors.append('"'"'Phase 4b roadmap status is Future'"'"')
for stale in ['"'"'no real cost/token threshold yet'"'"', '"'"'TBD (no per-provider/endpoint control yet)'"'"', '"'"'Phase 4b | Token/resource governance, model routing | Future |'"'"']:
    if stale in spec:
        errors.append('"'"'stale specification wording'"'"')
if '"'"'| Loop keeps continuing | `LAB_AGENT_LOOP_MAX_ROUNDS` closes via backstop reason |'"'"' in workflow:
    errors.append('"'"'stale workflow table row'"'"')
changelog = (docs / '"'"'project-changelog.md'"'"').read_text(encoding='"'"'utf-8'"'"')
for stale in ['"'"'396/396'"'"', '"'"'84/84'"'"']:
    if stale in changelog:
        errors.append(f'"'"'stale changelog count: {stale}'"'"')
for marker in ['"'"'406/406'"'"', '"'"'37/37'"'"', '"'"'131/131'"'"', '"'"'15/15'"'"']:
    if marker not in changelog:
        errors.append(f'"'"'missing changelog count: {marker}'"'"')
for pattern in [r'"'"'four'"'"', r'"'"'no flake'"'"']:
    if not re.search(pattern, changelog, re.I):
        errors.append(f'"'"'missing changelog marker: {pattern}'"'"')
if errors:
    print('"'"'AUTHORITATIVE DOCS CONTRACT FAIL: '"'"' + '"'"' | '"'"'.join(errors))
    sys.exit(1)
print('"'"'AUTHORITATIVE DOCS CONTRACT PASS: seven docs local links and line caps; 13 config names; exact Phase 5 status markers; known stale wording absent; changelog markers 406/406, 37/37, 131/131, 15/15, four/no-flake'"'"')
